# Better approach: find spatially separated structures using connected components of any non-zero cell

def find_structures(grid):
    """Find separate rectangular structures by grouping adjacent non-zero cells"""
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]

    # For each non-zero cell, find its connected component (of non-zero cells)
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and not visited[r][c]:
                # BFS to find all connected non-zero cells
                comp_cells = []
                queue = [(r, c)]
                visited[r][c] = True

                while queue:
                    cr, cc = queue.pop(0)
                    comp_cells.append((cr, cc))

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] != 0 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                # Compute bounding box
                min_r = min(cr for cr, cc in comp_cells)
                max_r = max(cr for cr, cc in comp_cells)
                min_c = min(cc for cr, cc in comp_cells)
                max_c = max(cc for cr, cc in comp_cells)

                components.append({
                    'cells': comp_cells,
                    'min_r': min_r, 'max_r': max_r,
                    'min_c': min_c, 'max_c': max_c,
                    'width': max_c - min_c + 1,
                    'height': max_r - min_r + 1
                })

    return components

