def find_frames(grid):
    """Identify frame-like structures"""
    rows, cols = len(grid), len(grid[0])

    # Find bounding box
    min_r, max_r = 0, len(grid)-1
    for r in range(len(grid)):
        for c in range(len(grid[r])):
            if grid[r][c] != 0:
                min_r = min(min_r, r)
                max_r = max(max_r, r)

    min_c, max_c = 0, len(grid[0])-1
    for r in range(min_r, max_r + 1):
        for c in range(len(grid[r])):
            if grid[r][c] != 0:
                min_c = min(min_c, c)
                max_c = max(max_c, c)

    bbox_w = max_c - min_c + 1
    bbox_h = max_r - min_r + 1

    # Find colors that appear on the perimeter (potential frames)
    perimeter_colors = set()
    inner_colors = set()

    # Check perimeter: top row, bottom row, left col, right col
    for r in [min_r, max_r]:
        for c in range(min_c, max_c + 1):
            val = grid[r][c]
            if val != 0:
                perimeter_colors.add(val)

    for c in [min_c, max_c]:
        for r in range(min_r + 1, max_r):
            val = grid[r][c]
            if val != 0 and val not in perimeter_colors:
                perimeter_colors.add(val)

    # All colors in bbox
    all_colors = set()
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            val = grid[r][c]
            if val != 0:
                all_colors.add(val)

    # Inner colors = all - perimeter
    inner_colors = all_colors - perimeter_colors

    return {
        'bbox': (min_r, max_r, min_c, max_c),
        'perimeter_colors': sorted(perimeter_colors),
        'inner_colors': sorted(inner_colors),
        'all_colors': sorted(all_colors),
        'bbox_dims': (bbox_h, bbox_w)
    }

