# Clean implementation of nesting order detection
def get_nesting_order_from_perimeter(grid, bbox):
    """Get colors ordered from outermost (perimeter) to innermost using BFS"""
    min_r, max_r, min_c, max_c = bbox
    rows, cols = len(grid), len(grid[0])

    # Build set of all non-zero cells in bounding box
    cell_colors = {}  # (r,c) -> color
    for r in range(min_r, max_r+1):
        for c in range(min_c, max_c+1):
            if grid[r][c] != 0:
                cell_colors[(r,c)] = grid[r][c]

    # Find perimeter colors (on the edge of bbox)
    perimeter_colors = set()
    for r in [min_r, max_r]:
        for c in range(min_c, max_c+1):
            if (r,c) in cell_colors:
                perimeter_colors.add(cell_colors[(r,c)])

    for c in [min_c, max_c]:
        for r in range(min_r+1, max_r+1):
            if (r,c) in cell_colors:
                perimeter_colors.add(cell_colors[(r,c)])

    # BFS inward through adjacent cells
    visited = set(perimeter_colors)
    queue = list(perimeter_colors)
    order = []

    while queue:
        current = queue.pop(0)
        # Find all neighbors with different color that haven't been visited
        neighbors = []
        for r in range(min_r, max_r+1):
            for c in range(min_c, max_c+1):
                if (r,c) in cell_colors and cell_colors[(r,c)] == current:
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = r + dr, c + dc
                        if (nr,nc) in cell_colors:
                            neighbor_color = cell_colors[(nr,nc)]
                            if neighbor_color != current and neighbor_color not in visited:
                                neighbors.append(neighbor_color)

        if not neighbors:
            continue

        for nxt in neighbors:
            visited.add(nxt)
            queue.append(nxt)
        order.append(current)

    return sorted(order)

