# Find connected components properly
def find_connected_components(grid):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 0 and not visited[r][c]:
                # BFS to find component
                comp = []
                queue = [(r,c)]
                visited[r][c] = True

                while queue:
                    curr_r, curr_c = queue.pop(0)
                    comp.append((curr_r, curr_c))

                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = curr_r + dr, curr_c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] != 0 and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                min_r, max_r = min(p[0] for p in comp), max(p[0] for p in comp)
                min_c, max_c = min(p[1] for p in comp), max(p[1] for p in comp)

                components.append({
                    'bbox': (min_r, max_r, min_c, max_c),
                    'colors': sorted(set(d1_in_full[r][c] for r,c in comp)),
                    'count': len(comp)
                })

    return components

